package com.logatron.investigation.web;
import com.logatron.investigation.application.InvestigationService;import com.logatron.investigation.domain.InvestigationModels.InvestigationResult;import com.logatron.investigation.web.InvestigationDtos.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/investigations") public class InvestigationController {private final InvestigationService investigations;public InvestigationController(InvestigationService i){investigations=i;}@PostMapping public InvestigationResult create(@AuthenticationPrincipal Jwt jwt,@RequestBody CreateInvestigationRequest input,HttpServletRequest request){return investigations.create(jwt,input,request);}@GetMapping("/{id}")public StoredInvestigation get(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id,HttpServletRequest request){return investigations.get(jwt,id,request);}}
